Q: Initialization of all elements of a multidimensional std::array to one default value A: <p><code>std::array</code> is an aggregate so you'd have to explicitly spell it out to actually <em>initialize</em> it with the values you want:</p>
<pre class="lang-cpp prettyprint-override"><code>std::array&lt;std::array&lt;double, 2&gt;, 3&gt; arr{{
    {1., 2.},
    {3., 4.},
    {5., 6.},
}};
</code></pre>
<p>If you want all rows to be the same, you could make one row that you copy upon initialization:</p>
<pre class="lang-cpp prettyprint-override"><code>std::array&lt;double, 2&gt; row{-1., -1.};
std::array&lt;std::array&lt;double, 2&gt;, 3&gt; arr{
    row, row, row
};
</code></pre>
<p>If you want a helper to deal with the initialization for an arbitrary amout of dimensions where the type doesn't need to be default constructible:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;utility&gt;

template &lt;class T, std::size_t... Is, class... Rest&gt;
constexpr auto make_md_array_impl(const T&amp; val, std::index_sequence&lt;Is...&gt;, Rest... rs) {
    if constexpr (sizeof...(Rest) != 0) {
        // recurse sizeof...(Is) times to create inner arrays
        return std::array{((void)Is, make_md_array_impl(val, rs...))...};
    } else {
        // inner most array, initialize it with sizeof...(Is) val's:
        return std::array{((void)Is, val)...};
    }
}

template &lt;std::size_t... Ns, class T&gt;
constexpr auto make_md_array(const T&amp; val) {
    return make_md_array_impl(val, std::make_index_sequence&lt;Ns&gt;{}...);
}
</code></pre>
<p>Usage:</p>
<pre><code>auto arr = make_md_array&lt;4, 3, 2&gt;(-1.); // similar to double[4][3][2] ...
// ... but is really std::array&lt;std::array&lt;std::array&lt;double, 2&gt;, 3&gt;, 4&gt;
</code></pre>
<p><a href="https://godbolt.org/z/Yz9rbqWe8" rel="nofollow noreferrer">Demo</a></p>

Q: item stock management system critique A: <p>As @Peter - Reinstate Monica said, this would be a better fit on the Code Review web site.</p>
<p>That said, just a few comments.</p>
<ol>
<li><p>You have a lot in the <code>item</code> class that deals with an entire collection of items, rather than a single item. I'd prefer an <code>item</code> class deal only with the details of a single item, and then have something like a <code>database</code> class that deals with a collection of them.</p>
</li>
<li><p>I would use an enumeration for the options, so you get something like:</p>
<pre class="lang-cpp prettyprint-override"><code>// rather than if (option == 1) {
if (option == database::input) {
    // code to enter an item
}
else if (option == database::modify_quantity) {
    // code to update quantity
}
else if (option == database::modify_cost) { 
    // code to update cost
}
// ...
</code></pre>
</li>
<li><p>I'd make up my mind about how to deal with the csv file. Either do like a spreadsheet where you read the data when you open it, modify in memory, and save when the user says so, or else make it a database where you to updates &quot;in place&quot; (which means probably not using a CSV file). But right now, you pretty routinely read and write the entire file when it's not really necessary.</p>
</li>
</ol>
<p>If you post to the Code Review site you'll probably get more detailed critiques though.</p>

Q: Read zip in zip for updating A: <p>I have compiled the entire previous answer into a ready-made class, taking into account the comments.</p>
<p>min Java 8</p>
<p>Replacing the file in the internal ZIP</p>
<pre><code>C:/
├── root.zip
│   ├── file1.txt
│   ├── folder/file2.txt
│   └── inner.zip 
│       ├── file_to_replace.txt
│       └── file3.txt
└── test.txt
</code></pre>
<pre><code>import java.io.*;
import java.nio.file.*;
import java.util.Enumeration;
import java.util.zip.*;

public class ZipReplacer {

    private static final String REPLACE_FILENAME = &quot;file_to_replace.txt&quot;;
    private static final String REPLACE_TARGET_FILENAME = &quot;test.txt&quot;;

    private static final Path ROOT_ZIP_PATH = Paths.get(&quot;root.zip&quot;);
    private static final Path OUTPUT_ZIP_PATH = Paths.get(&quot;output.zip&quot;);
    private static final Path REPLACE_PATH = Paths.get(REPLACE_TARGET_FILENAME);

    public static void main(String[] args) throws IOException {

        try (
                ZipFile zfParent = new ZipFile(ROOT_ZIP_PATH.toFile());
                OutputStream outStream = Files.newOutputStream(OUTPUT_ZIP_PATH,
                        StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
                ZipOutputStream outputStream = new ZipOutputStream(outStream)
        ) {
            Enumeration&lt;? extends ZipEntry&gt; entries = zfParent.entries();

            while (entries.hasMoreElements()) {

                ZipEntry entry = entries.nextElement();

                if (entry.getName().endsWith(&quot;.zip&quot;)) {
                    processNestedZip(zfParent, entry, outputStream);
                } else {
                    copyEntry(zfParent, entry, outputStream);
                }
            }
        }

        System.out.println(&quot;Done!&quot;);

    }

    private static void processNestedZip(
            ZipFile zfParent,
            ZipEntry entry,
            ZipOutputStream zfParentOutputStream
    ) throws IOException {

        byte[] innerZipBytes;
        try (InputStream is = zfParent.getInputStream(entry)) {
            innerZipBytes = is.readAllBytes();
        }
        byte[] patchedInnerZipBytes = patchInnerZip(innerZipBytes);

        zfParentOutputStream.putNextEntry(new ZipEntry(entry.getName()));
        zfParentOutputStream.write(patchedInnerZipBytes);
        zfParentOutputStream.closeEntry();
    }

    private static byte[] patchInnerZip(
            byte[] innerZipBytes
    ) throws IOException {
        try (
                ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
                ZipInputStream inputStream = new ZipInputStream(new ByteArrayInputStream(innerZipBytes));
                ZipOutputStream outputStream = new ZipOutputStream(byteArrayOutputStream)
        ) {
            ZipEntry entry;

            while ((entry = inputStream.getNextEntry()) != null) {

                if (REPLACE_FILENAME.equals(entry.getName())) {

                    //try (InputStream testFileStream = Files.newInputStream(REPLACE_PATH)) {

                        //testFileStream.transferTo(outputStream);

                        long size = Files.size(REPLACE_PATH);

                        CRC32 crc = new CRC32();
                        try (CheckedInputStream cis = new CheckedInputStream(Files.newInputStream(REPLACE_PATH), crc)) {
                            byte[] buffer = new byte[1024 * 8];
                            while (cis.read(buffer) != -1) {}
                        }

                        ZipEntry newEntry = new ZipEntry(REPLACE_TARGET_FILENAME);

                        entry.setMethod(ZipEntry.STORED);
                        entry.setSize(size);
                        entry.setCompressedSize(size);
                        entry.setCrc(crc.getValue());

                    outputStream.putNextEntry(newEntry);
/*
                        byte[] buffer = new byte[1024 * 8];
                        int len;
                        while ((len = testFileStream.read(buffer)) != -1) {
                            outputStream.write(buffer, 0, len);
                        }
                        outputStream.closeEntry();
*/
                        Files.copy(REPLACE_PATH, outputStream); // testFileStream.transferTo(outputStream);
                    //}
                } else {

                    outputStream.putNextEntry(new ZipEntry(entry.getName()));

                    byte[] buffer = new byte[8192];
                    int len;
                    while ((len = inputStream.read(buffer)) != -1) {
                        outputStream.write(buffer, 0, len);
                    }
                }

                outputStream.closeEntry();
                inputStream.closeEntry();

            }
            return byteArrayOutputStream.toByteArray();
        }
    }

    private static void copyEntry(
            ZipFile zipFile,
            ZipEntry entry,
            ZipOutputStream output
    ) throws IOException {

        output.putNextEntry(new ZipEntry(entry.getName()));
        try (InputStream input = zipFile.getInputStream(entry)) {
            input.transferTo(output);
        }
        output.closeEntry();
    }
}
</code></pre>
